fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let period: i32 = 256;
    let phase: i32 = t * 2 % (period * 2);
    let p: i32 = if phase < period { phase } else { period * 2 - phase };
    let s: i32 = (3 * p * p - p * p * p / 128) / 256;
    let size: i32 = 40 + s * 80 / 256;
    let g: i32 = 48 + s * 200 / 256;
    host::display::clear(0x000000);
    host::display::fill_rect(w / 2 - size / 2, h / 2 - size / 2, size, size, g * 65536 + g * 256 + g);
    host::display::present();
}
